    int currentIndex = 0;
    while (currentIndex < patternLength) {
        char currentChar = conversionPattern.charAt(currentIndex);
        switch (currentChar) {
            case 'd':
                result.append(event.getTimestamp());
                break;
            case 'l':
                result.append(event.getLocationInformation().fullInfo);
                break;
            case 'm':
                result.append(event.getMessage());
                break;
            case 'n':
                result.append("\n");
