public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    try {
        // Check if the graph is empty
        if (target.getVertices().size() == 0) {
            throw new IllegalArgumentException("The graph must not be empty");
        }
        // Check if the result map is empty
        if (resultMap.size() == 0) {
            throw new IllegalArgumentException("The result map must not be empty");
        }
        // Create a map of string labels to vertices
        Map<String, V> labelMap = new HashMap<>();
        for (String label : resultMap.keySet()) {
            V vertex = resultMap.get(label);
            if (vertex == null) {
                throw new IllegalArgumentException("Vertex not found for label: " + label);
            }
            labelMap.put(label, vertex);
        }
        // Create a list of all edges in the graph
        List<E> edges = new ArrayList<>();
        for (V vertex : target.getVertices()) {
            for (int i = 0; i < vertex.getDegree(); i++) {
                edges.add(target.getEdge(vertex, i));
            }
        }
        // Sort the edges by their labels
        Collections.sort(edges, new Comparator<E>() {
            @Override
            public int compare(E edge1, E edge2) {
                String label1 = target.getObject(edge1);
                String label2 = target.getObject(edge2);
                return label1.compareTo(label2);
            }
        });
        // Build the bipartite graph
        Graph<V, E> bipartiteGraph = new Graph<V, E>();
        for (E edge : edges) {
            V source = target.getHead(edge);
            V target = target.getTail(edge);
            E newEdge = bipartiteGraph.createEdge(source, target);
            bipartiteGraph.addEdge(newEdge);
        }
        // Return the bipartite graph
        return bipartiteGraph;
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Error generating bipartite graph", e);
    }
