protected int removeUnusedNodes() {
    List<Category> unusedCategories = new ArrayList<>();
    for (Category category : getCategories()) {
        if (!isUsed(category)) {
            unusedCategories.add(category);
        }
    }
    for (Category unusedCategory : unusedCategories) {
        removeCategory(unusedCategory);
    }
    return unusedCategories.size();
}

private boolean isUsed(Category category) {
    for (Category childCategory : category.getChildCategories()) {
        if (isUsed(childCategory)) {
            return true;
        }
    }
    for (Product product : category.getProducts()) {
        if (product.getCategory().equals(category)) {
            return true;
        }
    }
    return false;
}

private void removeCategory(Category category) {
    category.getParentCategory().getChildCategories().remove(category);
    category.getChildCategories().clear();
    category.getProducts().clear();
}
