/**
 * Removes any inactive nodes from the Category tree.
 * 
 * @param trees A list of Category Trees to be pruned
 */
public void removeUnusedNodes(List<Tree<Category>> trees) {
    for (Tree<Category> tree : trees) {
        pruneTree(tree);
    }
}

/**
 * Recursively traverse the tree and remove any inactive nodes, 
 * i.e. nodes that have no active children.
 * 
 * @param node The current node being visited
 */
public void pruneTree(Tree<Category> node) {
    // Base case: if node is inactive, return immediately
    if (!node.isActive()) {
        return;
    }

    // Recursive case: visit each child node and remove any inactive children
    for (Tree<Category> child : node.getChildren()) {
        pruneTree(child);
    }

    // If all children are inactive, mark this node as inactive
    if (node.getChildren().stream().allMatch(c -> !c.isActive())) {
        node.setActive(false);
    }
}

