protected int removeUnusedNodes() {
    // Step 1: Traverse the category tree and find all inactive nodes
    Set<Category> inactiveNodes = new HashSet<>();
    for (Category category : categories) {
        if (category.isActive()) {
            inactiveNodes.add(category);
        }
    }

    // Step 2: Remove the inactive nodes from the tree
    for (Category inactiveNode : inactiveNodes) {
        categories.remove(inactiveNode);
    }

    // Step 3: Return the number of removed nodes
    return inactiveNodes.size();
}

