public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnanalyzerange> timeRanges) throws IOException {

    // Define a list to store the thread snapshots in the specified time range
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Define a buffered reader to read the file line by line
    BufferedReader br = new BufferedReader(new FileReader(file));

    // Read the file line by line and parse the thread snapshots in the specified time range
    String line;
    while ((line = br.readLine()) != null) {
        if (line.startsWith("#")) {
            continue;
        }
        // Split the line into an array of words
        String[] words = line.split("\\s+");
        // Parse the thread id, timestamp, and stack trace
        String threadId = words[0];
        long timestamp = Long.parseLong(words[1]);
        List<StackFrame> stackTrace = new ArrayList<>();
        for (int i = 2; i < words.length; i++) {
            stackTrace.add(new StackFrame(words[i]));
        }

        // Create a thread snapshot with the parsed data
        ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, timestamp, stackTrace);

        // Check if the thread snapshot is in the specified time range
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                // Add the thread snapshot to the list
                threadSnapshots.add(threadSnapshot);
                break;
            }
        }
    }

    // Return the list of thread snapshots in the specified time range
    return threadSnapshots;
}
